pub(crate) const CREATE: &str = "CREATE TABLE ai_job_records (\n    job_id TEXT PRIMARY KEY,\n    finished_seconds INTEGER NOT NULL,\n    finished_nanos INTEGER NOT NULL CHECK (finished_nanos BETWEEN 0 AND 999999999),\n    payload TEXT NOT NULL\n) STRICT;\nCREATE INDEX ai_job_records_finished ON ai_job_records(finished_seconds, finished_nanos);\nCREATE TRIGGER ai_job_records_no_update BEFORE UPDATE ON ai_job_records BEGIN SELECT RAISE(ABORT, 'ai job records are append only'); END;\nCREATE TRIGGER ai_job_records_no_delete BEFORE DELETE ON ai_job_records BEGIN SELECT RAISE(ABORT, 'ai job records are append only'); END;\nCREATE TABLE investment_principles (\n    id INTEGER PRIMARY KEY CHECK (id = 1),\n    schema_version INTEGER NOT NULL CHECK (schema_version >= 1),\n    payload TEXT NOT NULL\n) STRICT;\nCREATE TRIGGER investment_principles_no_delete BEFORE DELETE ON investment_principles BEGIN SELECT RAISE(ABORT, 'investment principles are replaced, not deleted'); END;\n";
pub(crate) const INSERT_JOB: &str = "INSERT INTO ai_job_records(job_id, finished_seconds, finished_nanos, payload) VALUES (?1, ?2, ?3, ?4) ON CONFLICT(job_id) DO NOTHING";
pub(crate) const FIND_JOB: &str = "SELECT payload FROM ai_job_records WHERE job_id = ?1";
pub(crate) const JOBS_BETWEEN: &str = "SELECT payload FROM ai_job_records WHERE (finished_seconds > ?1 OR (finished_seconds = ?1 AND finished_nanos >= ?2)) AND (finished_seconds < ?3 OR (finished_seconds = ?3 AND finished_nanos <= ?4)) ORDER BY rowid";
pub(crate) const FIND_PRINCIPLES: &str =
    "SELECT schema_version, payload FROM investment_principles WHERE id = 1";
pub(crate) const UPSERT_PRINCIPLES: &str = "INSERT INTO investment_principles(id, schema_version, payload) VALUES (1, ?1, ?2) ON CONFLICT(id) DO UPDATE SET schema_version = excluded.schema_version, payload = excluded.payload";
